# Independent Gate-5 full-logit parity comparison over all 129 teacher-forced positions.
#
# Artifacts (generated by run_head_sweep2.cmd on 2026-10-13):
#   ref        : llama.cpp clone, llama_dump_logits_teacher_forced.exe, tinyllama-1.1b Q4_K_M
#   d2 cpu/gpu : deep2_parity_trace.exe, same 129 tokens, tinyllama-1.1b Q4_K_M
#
# This script is INDEPENDENT of tools/gate5_reverify_sweep.ps1: it recomputes
# every metric from the raw float32 artifacts with its own implementation, and
# additionally reports RMSE, per-position detail, the first divergent position,
# and the first divergent operator per position (Deep2 GPU-native vs CPU-native
# per-op dumps, since the independent reference only dumps final logits).
import json
import math
import os
import sys

import numpy as np

E = r"F:\rawrxd\evidence\GAP_AUDIT_2026-10-13\gate5"
N = 129
VOCAB = 32000
EXPECTED_BYTES = VOCAB * 4
OP_TOL = 1e-4  # per-op max-abs tolerance for "divergent operator" (gpu vs cpu path)

out = []


def say(s=""):
    out.append(s)
    print(s)


def load_f32(path):
    with open(path, "rb") as f:
        b = f.read()
    if len(b) != EXPECTED_BYTES:
        raise SystemExit("FAIL: %s has %d bytes, expected %d" % (path, len(b), EXPECTED_BYTES))
    return np.frombuffer(b, dtype="<f4").astype(np.float64)


def parse_trace(path):
    ops = []
    with open(path, "r", encoding="utf-8", errors="replace") as f:
        for line in f:
            line = line.strip()
            if not line.startswith("blk="):
                continue
            parts = line.split()
            blk = int(parts[0].split("=")[1])
            pc = int(parts[1].split("=")[1])
            op = int(parts[2].split("=")[1])
            name = parts[3].split("=", 1)[1]
            ops.append((pc, blk, op, name))
    ops.sort(key=lambda t: t[0])
    return ops


def op_sizes(path):
    sizes = {}
    with open(path, "r", encoding="utf-8", errors="replace") as f:
        for line in f:
            line = line.strip()
            if not line.startswith("blk="):
                continue
            parts = line.split()
            pc = int(parts[1].split("=")[1])
            size = int(parts[4].split("=")[1])
            sizes[pc] = size
    return sizes


def first_divergent_op(p, traces_cache, sizes_cache):
    """First operator (execution order) where GPU-native and CPU-native diverge."""
    if p not in traces_cache:
        traces_cache[p] = parse_trace(os.path.join(E, "d2_gpu_head", "d2_trace_pos%d.txt" % p))
        sizes_cache[p] = op_sizes(os.path.join(E, "d2_gpu_head", "d2_trace_pos%d.txt" % p))
    ops = traces_cache[p]
    worst = None
    for (pc, blk, op, name) in ops:
        fp = os.path.join(E, "d2_gpu_head", "d2_pos%d_blk%d_pc%d_%s.bin" % (p, blk, pc, name))
        cp = os.path.join(E, "d2_cpu_head", "d2_pos%d_blk%d_pc%d_%s.bin" % (p, blk, pc, name))
        if not (os.path.exists(fp) and os.path.exists(cp)):
            continue
        with open(fp, "rb") as f:
            g = np.frombuffer(f.read(), dtype="<f4").astype(np.float64)
        with open(cp, "rb") as f:
            c = np.frombuffer(f.read(), dtype="<f4").astype(np.float64)
        if g.shape != c.shape:
            continue
        d = float(np.max(np.abs(g - c)))
        if worst is None or d > worst[0]:
            worst = (d, pc, blk, name, int(g.size))
        if d > OP_TOL:
            return {"pos": p, "pc": pc, "blk": blk, "op": op, "name": name,
                    "maxabs": d, "size": int(g.size)}
    return {"pos": p, "pc": (worst[1] if worst else None), "blk": (worst[2] if worst else None),
            "name": (worst[3] if worst else None), "maxabs": (worst[0] if worst else 0.0),
            "size": (worst[4] if worst else None)}


# ---------- 1. Artifact validation (all positions, all sides, before any math) ----------
say("=== Gate 5 independent full-logit parity — %d positions ===" % N)
say("reference: llama.cpp teacher-forced dump (independent clone), Deep2 cpu/gpu: deep2_parity_trace.exe")
say("model: tinyllama-1.1b-chat-v1.0.Q4_K_M.gguf (32000 logits x float32 = 128000 bytes per position)")
say("")
bad = []
for p in range(N):
    for rel in (r"ref_head\ref_logits_pos%d.bin" % p,
                r"d2_cpu_head\d2_logits_pos%d.bin" % p,
                r"d2_gpu_head\d2_logits_pos%d.bin" % p):
        full = os.path.join(E, rel)
        if not os.path.exists(full):
            bad.append("missing: " + full)
        elif os.path.getsize(full) != EXPECTED_BYTES:
            bad.append("size: %s = %d" % (full, os.path.getsize(full)))
if bad:
    for b in bad:
        say("ARTIFACT FAIL: " + b)
    raise SystemExit("GATE5_FAIL: artifact validation failed")
say("artifact validation: PASS (%d positions x 3 sides, %d bytes each)" % (N, EXPECTED_BYTES))

# ---------- 2. Per-position metrics vs the independent reference ----------
results = {}
gate_pass = True
for side in ("cpu", "gpu"):
    rows = []
    for p in range(N):
        ref = load_f32(os.path.join(E, "ref_head", "ref_logits_pos%d.bin" % p))
        d2 = load_f32(os.path.join(E, "d2_%s_head" % side, "d2_logits_pos%d.bin" % p))
        if not np.all(np.isfinite(d2)):
            nonfinite = int(np.count_nonzero(~np.isfinite(d2)))
        else:
            nonfinite = 0
        diff = ref - d2
        maxabs = float(np.max(np.abs(diff)))
        rmse = float(np.sqrt(np.mean(diff * diff)))
        cos = float(np.dot(ref, d2) / (np.linalg.norm(ref) * np.linalg.norm(d2)))
        arg_r = int(np.argmax(ref))
        arg_d = int(np.argmax(d2))
        top2 = np.partition(ref, -2)
        margin = float(top2[-1] - top2[-2])
        agree = arg_r == arg_d
        rows.append({"pos": p, "cos": cos, "maxabs": maxabs, "rmse": rmse,
                     "argmax_ref": arg_r, "argmax_d2": arg_d, "agree": agree,
                     "margin": margin, "nonfinite": nonfinite})
    results[side] = rows
    n_match = sum(1 for r in rows if r["agree"])
    n_nonfinite = sum(r["nonfinite"] for r in rows)
    worst_cos_row = min(rows, key=lambda r: r["cos"])
    worst_abs_row = max(rows, key=lambda r: r["maxabs"])
    worst_rmse_row = max(rows, key=lambda r: r["rmse"])
    unexplain = [r for r in rows if (not r["agree"]) and r["margin"] >= r["maxabs"]]
    explained = [r for r in rows if (not r["agree"]) and r["margin"] < r["maxabs"]]
    first_argmax_miss = next((r["pos"] for r in rows if not r["agree"]), None)
    first_abs = next((r["pos"] for r in rows if r["maxabs"] > 1e-2), None)
    say("[%s] argmax agreement: %d/%d" % (side, n_match, N))
    say("[%s] worst cosine: %.10f (pos %d)" % (side, worst_cos_row["cos"], worst_cos_row["pos"]))
    say("[%s] worst max-abs: %.6f (pos %d)" % (side, worst_abs_row["maxabs"], worst_abs_row["pos"]))
    say("[%s] worst RMSE: %.6f (pos %d)" % (side, worst_rmse_row["rmse"], worst_rmse_row["pos"]))
    say("[%s] nonfinite logits: %d" % (side, n_nonfinite))
    say("[%s] first argmax divergence: %s ; first maxabs>1e-2: %s"
        % (side, "none" if first_argmax_miss is None else "pos %d" % first_argmax_miss,
           "none" if first_abs is None else "pos %d" % first_abs))
    say("[%s] disagreements: %d ; explained by margin<maxabs (boundary/measurement): %d ; UNEXPLAINED: %d"
        % (side, N - n_match, len(explained), len(unexplain)))
    for r in unexplain:
        say("    UNEXPLAINED pos %d: ref=%d d2=%d margin=%.6f maxabs=%.6f"
            % (r["pos"], r["argmax_ref"], r["argmax_d2"], r["margin"], r["maxabs"]))
    for r in explained:
        say("    explained pos %d: ref=%d d2=%d margin=%.6f maxabs=%.6f cos=%.7f rmse=%.4f"
            % (r["pos"], r["argmax_ref"], r["argmax_d2"], r["margin"], r["maxabs"], r["cos"], r["rmse"]))
    if n_nonfinite or unexplain:
        gate_pass = False
    say("")

# ---------- 3. GPU vs CPU per-op divergence: first divergent operator per position ----------
say("=== first divergent operator per position (Deep2 GPU-native vs CPU-native dumps, tol %.0e) ===" % OP_TOL)
say("(the independent llama.cpp reference only dumps final logits, so the per-op")
say(" comparison is between Deep2's two native execution paths)")
traces_cache, sizes_cache = {}, {}
op_div = []
for p in range(N):
    fd = first_divergent_op(p, traces_cache, sizes_cache)
    op_div.append(fd)
    say("pos %3d: first divergent op pc=%s blk=%s name=%-14s maxabs=%.6f size=%s"
        % (p, fd["pc"], fd["blk"], fd["name"], fd["maxabs"], fd["size"]))

# ---------- 4. Verdict ----------
gpu_miss = [r["pos"] for r in results["gpu"] if not r["agree"]]
say("")
say("POSITIONS=%d" % N)
say("GPU argmax matches: %d/%d" % (N - len(gpu_miss), N))
verdict = "PASS" if gate_pass else "FAIL"
say("PARITY_VERDICT=%s" % verdict)

with open(os.path.join(E, "gate5_independent_logits.txt"), "w", encoding="utf-8") as f:
    f.write("\n".join(out) + "\n")
with open(os.path.join(E, "gate5_independent_logits.json"), "w", encoding="utf-8") as f:
    json.dump({"positions": N, "vocab": VOCAB, "cpu": results["cpu"], "gpu": results["gpu"],
               "first_divergent_ops": op_div, "verdict": verdict}, f, indent=1)
print("wrote gate5_independent_logits.txt/.json")
